const skill = (id, name, icon, description, type, damageMultiplier, manaCost, cooldown, requiredLevel, scalingStat, extra = {}) => ({
  id, name, icon, description, type, damageMultiplier, manaCost, cooldown, requiredLevel, scalingStat,
  classId:extra.classId, specialization:extra.specialization||null, maxLevel:5, effects:[], duration:0, chance:1,
  requirements:{level:requiredLevel,specialization:extra.specialization||null}, levelScaling:{damage:.12}, ...extra
});

// V8: una progresión compartida y data-driven para habilidades base y de
// especialización. Los niveles 3–5 cambian coste, ritmo o interacción; no son
// únicamente incrementos lineales de daño.
function buildSkillUpgrades(skillData){
  const damaging=['physical','magical','hybrid'].includes(skillData.type),dot=skillData.tags?.includes('dot')||['burn','bleed','poison','curse'].includes(skillData.statusEffect),control=['freeze','stun'].includes(skillData.statusEffect),support=['heal','shield','buff','debuff','restore','summon'].includes(skillData.type);
  return [
    {level:2,description:damaging||skillData.type==='heal'?'Potencia base +10%.':skillData.type==='shield'?'Escudo +10% de escalado.':'Duración +1 turno.',...(damaging||skillData.type==='heal'?{damageMultiplier:.10}:skillData.type==='shield'?{statusPower:.10}:{duration:1})},
    {level:3,description:damaging?'Probabilidad crítica +5%.':'Coste de maná -3.',...(damaging?{bonusCrit:5}:{manaCost:-3})},
    {level:4,description:'Cooldown -1 turno.',cooldown:-1},
    {level:5,description:dot?'Aplica 1 stack adicional.':control?'Control +20% de probabilidad.':skillData.type==='summon'?'Invoca 1 aliado adicional.':skillData.type==='heal'?'Curación +15% de escalado.':skillData.type==='shield'?'Escudo +15% de escalado.':skillData.type==='restore'?'Restaura 6% más de maná.':support?'Duración +1 turno.':'Potencia base +15%.',...(dot?{statusStacks:1}:control?{procChance:.20}:skillData.type==='summon'?{summonCount:1}:skillData.type==='heal'?{damageMultiplier:.15}:skillData.type==='shield'?{statusPower:.15}:skillData.type==='restore'?{manaRestore:.06}:support?{duration:1}:{damageMultiplier:.15})}
  ];
}

function getSkillAtLevel(skillData,level=1,choices={}){
  if(!skillData)return null;const effective={...skillData},upgrades=skillData.upgrades||buildSkillUpgrades(skillData);
  for(const upgrade of upgrades)if(level>=upgrade.level)for(const [key,value] of Object.entries(upgrade))if(!['level','description'].includes(key))effective[key]=Math.max(0,(effective[key]||0)+value);
  for(const choice of skillData.modifierChoices||[]){const selected=choice.options.find(option=>option.id===choices[choice.unlockLevel]);if(level>=choice.unlockLevel&&selected)for(const [key,value] of Object.entries(selected.modifiers||{}))effective[key]=Math.max(0,(effective[key]||0)+value);}
  effective.level=Math.max(1,Math.min(skillData.maxLevel||5,level));effective.upgrades=upgrades;return effective;
}

