const parse=v=>{const [id,name,icon]=v.split('|');return {id,name,icon};};
function makeEnemy(raw,zone,zoneIndex,index,count){
  const level=Math.round(zone[3][0]+(zone[3][1]-zone[3][0])*(index/Math.max(1,count-1)));
  const boss=index===count-1, miniboss=!boss&&index===count-2;
  const scale=Math.pow(1.115,level-1), baseHp=Math.round((68+level*11)*scale), baseAttack=Math.round((10+level*2.1)*Math.pow(1.055,level-1));
  const family=index%4===1?(zoneIndex%2?'spirit':'beast'):index%5===2?'construct':zone[4];
  const archetypes=['warrior','tank','assassin','archer','mage','healer','summoner','berserker','controller'],archetype=boss?'boss':archetypes[(zoneIndex+index)%archetypes.length],signature={warrior:'Tajo Marcial',tank:'Golpe de Bastión',assassin:'Hoja Ejecutora',archer:'Flecha Dentada',mage:'Descarga Arcana',healer:'Luz Marchita',summoner:'Asalto de la Horda',berserker:'Frenesí',controller:'Grilletes'}[archetype]||'Poder de fase';
  return {id:raw.id,name:raw.name,icon:raw.icon,iconId:`enemy_${raw.id}`,assetId:`enemy.${raw.id}`,level,family,archetype,zone:zone[0],hp:Math.round(baseHp*(boss?2.2:miniboss?1.45:1)),attack:Math.round(baseAttack*(boss?1.28:miniboss?1.12:1)),magic:Math.round(baseAttack*(['spirit','demon','arcane','void','celestial'].includes(family)?1.05:.55)),defense:Math.round(4+level*2.15),resistance:Math.round(3+level*1.85),speed:Math.round(8+level*.7),crit:5+Math.floor(level/10),skills:[{name:boss?`Cataclismo de ${raw.name}`:signature,chance:boss?.4:.32,multiplier:boss?1.65:archetype==='assassin'?1.5:1.28,statusEffect:archetype==='controller'?'stun':['burn','poison','bleed','curse','stun'][zoneIndex%5],duration:2,interruptible:true}],statuses:[],xp:Math.round((55+level*18)*(boss?2.5:miniboss?1.5:1)),gold:Math.round((22+level*7)*(boss?2.1:miniboss?1.4:1)),lootTable:`${zone[0]}Loot`,materials:[zone[5]],boss,miniboss,
    phases:boss?[{at:.72,name:'FASE II',damage:1.15,statusEffect:['burn','poison','curse'][zoneIndex%3],shield:.12},{at:.42,name:'FASE FINAL',damage:1.3,statusEffect:'vulnerable',heal:zoneIndex%3===0?.08:0,resistanceShift:true}]:[]};
}

const MAPS=ZONES.map((z,zi)=>({id:z[0],name:z[1],icon:z[2],iconId:`zone_${z[0]}`,assetId:`zone.${z[0]}`,range:`${z[3][0]}–${z[3][1]}`,minLevel:z[3][0],maxLevel:z[3][1],family:z[4],material:z[5],nodes:z[6].map(v=>parse(v).id),lootTable:`${z[0]}Loot`,eventPool:zi<5?['invasion','ambush','caravan']:['portal','rareBoss','elementalStorm'],recipeId:`v8Recipe${String(zi+1).padStart(2,'0')}`,reputation:['aether','iron','arcane','abyss'][zi%4],boss:parse(z[6].at(-1)).id}));
const ENEMIES={};
ZONES.forEach((zone,zi)=>zone[6].map(parse).forEach((raw,i,all)=>ENEMIES[raw.id]=makeEnemy(raw,zone,zi,i,all.length)));

