[['forestShaman','Chamán Goblin','🪄',4,'goblin','shadowForest'],['graveHound','Sabueso Sepulcral','🐕',9,'undead','cursedCemetery'],['runeKeeper','Custodio Rúnico','🗿',14,'construct','ancientRuins'],['emberDrake','Draco de Brasas','🐲',19,'dragon','fireMountains'],['voidLeech','Sanguijuela del Vacío','🪱',24,'demon','eternalAbyss']].forEach(([id,name,icon,level,family,zone])=>{
  const base=ENEMIES[MAPS.find(m=>m.id===zone).nodes[1]];ENEMIES[id]={...base,id,name,icon,level,family,zone,boss:false,miniboss:false};
});

function createEncounter(enemyId,{difficulty='normal',eliteChance=.09,forceElite=false}={}){
  const base=ENEMIES[enemyId];if(!base)return null;
  const mult={normal:1,veteran:1.45,nightmare:2.05,abyssal:2.7}[difficulty]||1;
  const enemy=structuredClone(base);enemy.hp=Math.round(enemy.hp*mult);enemy.attack=Math.round(enemy.attack*mult);enemy.magic=Math.round(enemy.magic*mult);enemy.defense=Math.round(enemy.defense*Math.sqrt(mult));enemy.resistance=Math.round(enemy.resistance*(1+(mult-1)*.25));enemy.speed=Math.round(enemy.speed*(1+(mult-1)*.08));enemy.xp=Math.round(enemy.xp*({normal:1,veteran:1.3,nightmare:1.75,abyssal:2.25}[difficulty]||1));enemy.gold=Math.round(enemy.gold*({normal:1,veteran:1.25,nightmare:1.6,abyssal:2.05}[difficulty]||1));
  if(!enemy.boss&&(forceElite||Math.random()<eliteChance)){
    const keys=Object.keys(ELITE_AFFIXES),count=difficulty==='abyssal'?3:difficulty==='nightmare'?2:1,ids=[];while(ids.length<count){const id=keys[Math.floor(Math.random()*keys.length)];if(!ids.includes(id))ids.push(id);}enemy.elite=true;enemy.eliteAffixes=ids;enemy.eliteAffix=ids[0];for(const id of ids){const affix=ELITE_AFFIXES[id];enemy.hp=Math.round(enemy.hp*affix.hp);enemy.attack=Math.round(enemy.attack*affix.damage);enemy.defense=Math.round(enemy.defense*(affix.defense||1));}enemy.name=`${ids.map(id=>ELITE_AFFIXES[id].name).join(' · ')} · ${enemy.name}`;enemy.xp=Math.round(enemy.xp*(1.8+(count-1)*.45));enemy.gold=Math.round(enemy.gold*(1.7+(count-1)*.4));
  }
  const tagByName={fuego:'fire',hielo:'ice',veneno:'poison',sombra:'shadow',sagrado:'holy','físico':'physical',magia:'arcane'},trait=FAMILY_TRAITS[enemy.family];for(const tag of ['fire','ice','poison','shadow','holy','physical'])enemy[`${tag}Resistance`]=tag===tagByName[trait?.resistance]?30:tag===tagByName[trait?.weakness]?-20:0;enemy.controlResistance=enemy.boss?.45:enemy.elite?.2:0;
  enemy.maxHp=enemy.hp;enemy.difficulty=difficulty;
  return enemy;
}


