const BRANCHES = {
  warrior:[['BERSERKER','berserker','brutalStrike','bleed'],['GUARDIÁN','guardian','shieldSlam','fortified'],['MAESTRO DE ARMAS','weaponMaster','weaponChain','vulnerable']],
  mage:[['PIROMANTE','pyromancer','fireball','burn'],['CRIOMANTE','cryomancer','frostNova','freeze'],['ARCANISTA','arcanist','arcaneStorm','vulnerable']],
  rogue:[['ASESINO','assassin','shadowExecution','bleed'],['SOMBRA','shadow','ambush','vulnerable'],['VENENOS','poisons','deadlyPoison','poison']],
  paladin:[['PROTECTOR','protector','divineShield','fortified'],['VENGADOR','avenger','holyStrike','vulnerable'],['LUMINARIO','luminary','healingLight','fortified']],
  necromancer:[['INVOCADOR','summoner','summonSkeleton','curse'],['HEMOMANTE','hemomancer','lifeDrain','bleed'],['SEÑOR DE PLAGAS','plagueLord','plagueCloud','poison']]
};

const ICONS=['✦','⚔️','◆','🛡️','⏳','🔥','💠','👑','🌟'];
const EFFECTS=[
  {damagePct:.03},{crit:2},{maxHp:18},{defense:3},{cooldownReduction:.04},{resourceGainPct:.12},{damagePct:.06},{critDamage:10},{damagePct:.12}
];

function makeBranch(classId,[branch,specialization,skillId,status],branchIndex){
  const nodes=Array.from({length:20},(_,tier)=>{
    const id=`${classId}-${branchIndex}-${tier}`;
    const extendedEffects=[...EFFECTS,{maxHp:24},{damagePct:.04},{resistance:4},{resourceGainPct:.08},{crit:2},{defense:4},{cooldownReduction:.03},{damagePct:.07}];
    const effect={...(extendedEffects[tier]||{})};
    const labels=['Disciplina I','Dominio','Temple','Disciplina II','Flujo','Catalizador','Maestría','Ascensión','Legado','Resistencia','Impulso','Voluntad','Técnica','Instinto','Fortaleza','Cadencia','Trascendencia','CAPSTONE OFENSIVO','CAPSTONE DEFENSIVO','CAPSTONE DE RECURSO'];
    const data={id,name:`${labels[tier]} · ${branch}`,
      icon:ICONS[tier%ICONS.length],tier,requires:tier?(tier>=17?`${classId}-${branchIndex}-16`:`${classId}-${branchIndex}-${tier-1}`):null,effect,specialization,
      description:Object.entries(effect).map(([k,v])=>`${k} +${v<1?Math.round(v*100)+'%':v}`).join(', ')};
    if(tier===4){data.skillMod={skillId,cooldown:-1};data.description=`${skillId}: reduce su cooldown en 1.`;}
    if(tier===6){data.skillMod={skillId,addStatus:status,stacks:1};data.description=`${skillId} aplica ${status} adicional.`;}
    if(tier===7){data.skillMod={skillId,resourceGain:1};data.description=`${skillId} genera recurso de clase adicional.`;}
    if(tier===12){data.skillMod={skillId,cooldown:-1,resourceGain:1};data.description=`${skillId}: reduce cooldown y genera recurso adicional.`;}
    if(tier===15){data.skillMod={skillId,addStatus:status,stacks:2};data.description=`${skillId} aplica dos cargas adicionales de ${status}.`;}
    if(tier>=17){
      data.capstone=true;data.choiceGroup=`${specialization}-capstone`;
      if(tier===17){data.effect={damagePct:.16,critDamage:14};data.description='Final ofensivo: aumenta daño y potencia golpes críticos.';}
      if(tier===18){data.effect={damageReduction:.1,maxHp:55,shieldPower:8};data.description='Final defensivo: reduce daño y fortalece vida y escudos.';}
      if(tier===19){data.effect={resourceGainPct:.2,cooldownReduction:.06};data.description='Final de recurso: acelera generación y rotación de habilidades.';}
    }
    return data;
  });
  return {branch,specialization,nodes};
}

const TALENTS=Object.fromEntries(Object.entries(BRANCHES).map(([classId,branches])=>[classId,branches.map((b,i)=>makeBranch(classId,b,i))]));

function findTalent(classId,id){return TALENTS[classId]?.flatMap(b=>b.nodes).find(n=>n.id===id)||null;}


