function currentWorldBoss(date=new Date()){const day=Math.floor(Date.UTC(date.getUTCFullYear(),date.getUTCMonth(),date.getUTCDate())/86400000);return WORLD_BOSSES[((day%WORLD_BOSSES.length)+WORLD_BOSSES.length)%WORLD_BOSSES.length];}

