function localAffixRotation(date=new Date()){
  const epoch=Math.floor(Date.UTC(date.getUTCFullYear(),date.getUTCMonth(),date.getUTCDate())/86400000),week=Math.floor(epoch/7);
  return [0,1,2].map(offset=>KEY_AFFIXES[(week+offset*2)%KEY_AFFIXES.length]);
}

function makeExpedition(tier=1,seed=Date.now()){
  const modifierIds=Object.keys(EXPEDITION_MODIFIERS),modifier=modifierIds[Math.abs(seed)%modifierIds.length];
  return {id:`exp-${seed}`,tier:Math.max(1,Math.min(5,tier)),seed,stage:0,path:[],relics:[],modifier,status:'active',reward:{gold:0,materials:0},startedAt:Date.now()};
}


/* === js/data/assets.js === */
// Registro visual único V10. Prioridad: assetId -> iconId -> fallbackEmoji.
// Las rutas quedan vacías hasta que exista arte propio y el sprite SVG local
// sustituye progresivamente los emojis de interfaz sin alterar datos del juego.
const ASSETS={classes:{},zones:{},enemies:{},items:{},skills:{},pets:{},mounts:{},npcs:{},materials:{}};

const ICON_IDS=new Set(['home','map','hero','bag','talents','more','sword','axe','dagger','staff','bow','helmet','armor','gloves','boots','ring','amulet','relic','hp','mana','exp','energy','gold','gem','attack','defense','critical','speed','fire','ice','lightning','arcane','poison','bleed','summon','heal','shield','quest','boss','loot','crafting','expedition','dungeon','event','shop','lock','check']);

function registerAsset(kind,id,src=null){if(!ASSETS[kind])ASSETS[kind]={};ASSETS[kind][id]=src;return `${kind}.${id}`;}

function assetPath(assetId){if(!assetId)return null;const [kind,...parts]=String(assetId).split('.'),id=parts.join('.');return ASSETS[kind]?.[id]||null;}

function iconMarkup(iconId,fallbackEmoji='✦',className='rpg-icon'){
  return ICON_IDS.has(iconId)?`<svg class="${className}" aria-hidden="true"><use href="#${iconId}"></use></svg>`:`<span class="${className} fallback-icon" aria-hidden="true">${fallbackEmoji}</span>`;
}

function visualMarkup(entity,{className='',alt=''}={}){
  const src=assetPath(entity?.assetId),fallback=entity?.fallbackEmoji||entity?.icon||'✦';
  if(src)return `<img class="${className}" src="${src}" alt="${alt||entity?.name||''}">`;
  if(entity?.iconId)return iconMarkup(entity.iconId,fallback,className||'rpg-icon');
  return `<span class="${className} fallback-icon" aria-hidden="true">${fallback}</span>`;
}

function registerDataAssets(kind,entries){for(const entry of entries)if(entry?.id)registerAsset(kind,entry.id,null);}


