function calculatePower(s,playerOrLevel=1){const p=typeof playerOrLevel==='object'?playerOrLevel:null,level=p?.level||playerOrLevel;const equipmentPower=p?Object.values(p.equipment||{}).filter(Boolean).reduce((n,i)=>n+(i.itemPower||0)+(i.upgrade||0)*8,0):0;const talentPower=p?(p.talents?.length||0)*10:0,skillPower=p?Object.values(p.skillLevels||{}).reduce((n,l)=>n+l*3,0):0;return Math.round(s.maxHp*.16+s.maxMana*.08+s.attack*2.5+s.magic*2.5+s.defense*2+s.resistance+s.agility+s.crit*1.2+level*8+equipmentPower+talentPower+skillPower);}

