function dismantleItem(game,id){const p=game.player,i=p.inventory.findIndex(x=>(x.uid===id||x.id===id)&&!x.favorite&&!x.locked);if(i<0)return null;const [item]=p.inventory.splice(i,1),mult=RARITIES[item.rarity]?.mult||1,amount=Math.max(1,Math.round((item.level||1)*.35*mult)),material=['weapon','offhand'].includes(item.slot)?'iron':item.slot==='amulet'||item.slot==='ring'?'crystal':'hide';p.materials[material]=(p.materials[material]||0)+amount;progressEvent(game,'collect',amount,material);if(['legendary','mythic'].includes(item.rarity)){p.materials.legendaryShard=(p.materials.legendaryShard||0)+1;progressEvent(game,'collect',1,'legendaryShard');}game.statistics.itemsSalvaged++;progressEvent(game,'salvage',1);saveGame(game);return {material,amount};}
function upgradeEquipment(game,id){const item=[...game.player.inventory,...Object.values(game.player.equipment)].find(i=>i&&(i.uid===id||i.id===id));if(!item||item.type!=='equipment'||item.upgrade>=10)return null;const next=item.upgrade+1,cost=Math.round(30*Math.pow(1.42,next)+(item.level||1)*8),iron=Math.max(1,Math.ceil(next/2));if(game.player.gold<cost||(game.player.materials.iron||0)<iron)return null;game.player.gold-=cost;game.player.materials.iron-=iron;item.upgrade=next;item.itemPower+=Math.round(5+item.level*.3);game.statistics.itemsUpgraded++;progressEvent(game,'upgrade',1);saveGame(game);return {level:next,cost,iron};}
function applyRune(game,itemId,runeId){const item=findOwnedItem(game,itemId);if(!item||!RUNES[runeId]||(item.runes?.length||0)>=item.runeSlots||(game.player.runes[runeId]||0)<1)return false;game.player.runes[runeId]--;item.runes.push(runeId);saveGame(game);return true;}
function removeRune(game,itemId,index){const item=findOwnedItem(game,itemId),runeId=item?.runes?.[index],cost=50;if(!runeId||game.player.gold<cost)return null;game.player.gold-=cost;item.runes.splice(index,1);game.player.runes[runeId]=(game.player.runes[runeId]||0)+1;saveGame(game);return {runeId,cost};}
function applyGem(game,itemId,gemId){const item=findOwnedItem(game,itemId);if(!item||!GEMS[gemId]||(item.gems?.length||0)>=(item.gemSlots||0)||(game.player.gems[gemId]||0)<1)return false;game.player.gems[gemId]--;item.gems.push(gemId);saveGame(game);return true;}
function removeGem(game,itemId,index){const item=findOwnedItem(game,itemId),gemId=item?.gems?.[index],cost=25+(GEMS[gemId]?.tier||1)*20;if(!gemId||game.player.gold<cost)return null;game.player.gold-=cost;item.gems.splice(index,1);game.player.gems[gemId]=(game.player.gems[gemId]||0)+1;saveGame(game);return {gemId,cost};}
function applyMechanicRune(game,itemId,runeId){const item=findOwnedItem(game,itemId);if(!item||!MECHANIC_RUNES[runeId]||(item.mechanicRunes?.length||0)>=(item.mechanicRuneSlots||0)||(game.player.mechanicRunes[runeId]||0)<1)return false;game.player.mechanicRunes[runeId]--;item.mechanicRunes.push(runeId);saveGame(game);return true;}
function removeMechanicRune(game,itemId,index){const item=findOwnedItem(game,itemId),runeId=item?.mechanicRunes?.[index];if(!runeId||game.player.gold<80)return null;game.player.gold-=80;item.mechanicRunes.splice(index,1);game.player.mechanicRunes[runeId]=(game.player.mechanicRunes[runeId]||0)+1;saveGame(game);return {runeId,cost:80};}
function findOwnedItem(game,id){return [...game.player.inventory,...Object.values(game.player.equipment).filter(Boolean)].find(i=>i?.id===id||i?.uid===id);}

function reforgeAffix(game,itemId,affixId){const item=findOwnedItem(game,itemId),index=item?.affixes?.indexOf(affixId);if(!item||index<0)return null;const count=item.reforgeCount||0,cost=Math.round(120+(item.level||1)*16+count*85),stone=1+Math.floor(count/3);if(game.player.gold<cost||(game.player.materials.reforgeStone||0)<stone)return null;const currentKey=affixId,candidates=Object.keys(item.stats||{}).filter(k=>k!==currentKey);const pool=['attack','magic','defense','maxHp','maxMana','crit','agility','resistance','lifeSteal','physicalDamage','magicDamage'].filter(k=>k!==currentKey&&!candidates.includes(k));if(!pool.length)return null;const nextKey=pool[Math.floor(Math.random()*pool.length)],oldValue=item.stats[currentKey]||1,newValue=Math.max(1,Math.round(oldValue*(.8+Math.random()*.45)));delete item.stats[currentKey];item.stats[nextKey]=newValue;item.affixes[index]=nextKey;item.reforgeCount=count+1;game.player.gold-=cost;game.player.materials.reforgeStone-=stone;saveGame(game);return {from:currentKey,to:nextKey,value:newValue,cost,stone};}

function transmute(game,type,id){const p=game.player;if(type==='gem'){const gem=GEMS[id];if(!gem||gem.tier>=5||(p.gems[id]||0)<3)return null;const next=Object.values(GEMS).find(g=>g.family===gem.family&&g.tier===gem.tier+1);if(!next)return null;p.gems[id]-=3;p.gems[next.id]=(p.gems[next.id]||0)+1;saveGame(game);return next;}const tiers={crystal:['crystal','runeShard',5,1],legendary:['legendaryShard','bossCore',4,1],pet:['petEssence','reforgeStone',5,1]},pair=tiers[type];if(!pair||(p.materials[pair[0]]||0)<pair[2])return null;p.materials[pair[0]]-=pair[2];p.materials[pair[1]]=(p.materials[pair[1]]||0)+pair[3];progressEvent(game,'collect',pair[3],pair[1]);saveGame(game);return MATERIALS[pair[1]];}

function addStack(inventory,item){const stack=inventory.find(i=>i.type===item.type&&i.baseId===item.baseId&&i.type==='consumable');if(stack)stack.quantity+=item.quantity||1;else inventory.push(item);}
function learnRecipe(game,id){if(!RECIPES.some(r=>r.id===id)||game.player.learnedRecipes.includes(id))return false;game.player.learnedRecipes.push(id);saveGame(game);return true;}
function craftRecipe(game,id){const recipe=RECIPES.find(r=>r.id===id),p=game.player,newInventorySlot=recipe&&(recipe.result.kind==='equipment'||recipe.result.kind==='consumable'&&!p.inventory.some(i=>i.type==='consumable'&&i.baseId===recipe.result.id));if(!recipe||!p.learnedRecipes.includes(id)||p.level<(recipe.requiredLevel||1)||p.gold<recipe.gold||newInventorySlot&&p.inventory.length>=p.inventoryCapacity||Object.entries(recipe.cost).some(([m,n])=>(p.materials[m]||0)<n))return null;for(const [m,n] of Object.entries(recipe.cost))p.materials[m]-=n;p.gold-=recipe.gold;let result;if(recipe.result.kind==='consumable'){result=createConsumable(recipe.result.id,recipe.result.quantity);addStack(p.inventory,result);}else if(recipe.result.kind==='equipment'){result=generateItem(p.level,{template:ITEM_TEMPLATES.find(t=>t.baseId===recipe.result.template),rarity:recipe.tier>=5?'epic':recipe.tier>=3?'rare':'uncommon',classId:p.classId,specialization:p.specialization});p.inventory.push(result);}else if(recipe.result.kind==='gem'){p.gems[recipe.result.id]=(p.gems[recipe.result.id]||0)+(recipe.result.quantity||1);result=GEMS[recipe.result.id];}else if(recipe.result.kind==='material'){p.materials[recipe.result.id]=(p.materials[recipe.result.id]||0)+(recipe.result.quantity||1);result=MATERIALS[recipe.result.id];}else if(recipe.result.kind==='mechanicRune'){p.mechanicRunes[recipe.result.id]=(p.mechanicRunes[recipe.result.id]||0)+(recipe.result.quantity||1);result=MECHANIC_RUNES[recipe.result.id];}else{p.runes[recipe.result.id]=(p.runes[recipe.result.id]||0)+(recipe.result.quantity||1);result=RUNES[recipe.result.id];}game.statistics.itemsCrafted++;progressEvent(game,'craft',1,recipe.profession);saveGame(game);return result;}
function buyMerchantItem(game,index){const safeIndex=whole(index,0,9999,-1),stock=Number(index)===safeIndex?getMerchantStock()[safeIndex]:null,p=game.player,newSlot=stock&&(stock.kind==='equipment'||stock.kind==='consumable'&&!p.inventory.some(i=>i.type==='consumable'&&i.baseId===stock.id)),price=whole(stock?.price,0,Number.MAX_SAFE_INTEGER,0);p.gold=whole(p.gold,0,Number.MAX_SAFE_INTEGER,0);if(!stock||p.gold<price||(newSlot&&p.inventory.length>=p.inventoryCapacity)||(stock.kind==='recipe'&&p.learnedRecipes.includes(stock.id)))return false;p.gold-=price;if(stock.kind==='consumable')addStack(p.inventory,createConsumable(stock.id,1));else if(stock.kind==='material'){const amount=whole(stock.quantity,1,9999,1);p.materials[stock.id]=whole(p.materials[stock.id],0,Number.MAX_SAFE_INTEGER,0)+amount;progressEvent(game,'collect',amount,stock.id);}else if(stock.kind==='gem')p.gems[stock.id]=whole(p.gems[stock.id],0,9999,0)+1;else if(stock.kind==='recipe')p.learnedRecipes.push(stock.id);else{const template=ITEM_TEMPLATES.find(t=>t.baseId===stock.id);if(!template){p.gold+=price;return false;}p.inventory.push(generateItem(Math.max(1,p.level),{template,rarity:'common',classId:p.classId,specialization:p.specialization}));}saveGame(game);return true;}
function moveBankItem(game,id,toBank=true){const p=game.player,bank=p.bank.tabs[0];if(toBank){const i=p.inventory.findIndex(x=>x.uid===id||x.id===id);if(i<0||bank.length>=p.bank.capacity)return false;bank.push(p.inventory.splice(i,1)[0]);}else{const i=bank.findIndex(x=>x.uid===id||x.id===id);if(i<0||p.inventory.length>=p.inventoryCapacity)return false;p.inventory.push(bank.splice(i,1)[0]);}saveGame(game);return true;}

function toggleSelectedSkill(game,id){const p=game.player,skill=SKILLS[id]||SPEC_SKILLS[id];if(!skill||skill.classId&&skill.classId!==p.classId||p.level<skill.requiredLevel)return false;const spec=getSpecV4(p.classId,p.specialization);if(SPEC_SKILLS[id]&&!spec?.skills.includes(id))return false;const index=p.selectedSkills.indexOf(id);if(index>=0){p.selectedSkills.splice(index,1);}else{if(p.selectedSkills.length>=5)return false;p.selectedSkills.push(id);}saveGame(game);return true;}

function saveLoadout(game,index,name='BUILD'){const p=game.player;if(index<0||index>2||!p.specialization)return false;p.loadouts[index]={name:name.slice(0,18),specialization:p.specialization,talents:clone(p.talents),skills:clone(p.selectedSkills),equipment:Object.fromEntries(Object.entries(p.equipment).map(([slot,item])=>[slot,itemUid(item)])),activePet:p.pets.active||null,savedAt:Date.now()};p.activeLoadout=index;saveGame(game);return true;}
function applyLoadout(game,index){const p=game.player,l=p.loadouts[index];if(!l||!getSpecV4(p.classId,l.specialization)||!isObject(l.equipment))return null;const bankItems=(p.bank?.tabs||[]).flat(),allItems=[...p.inventory,...Object.values(p.equipment).filter(Boolean),...bankItems],byUid=new Map();for(const item of allItems){byUid.set(itemUid(item),item);byUid.set(item.id,item);}const wanted=Object.values(l.equipment).filter(Boolean),duplicateRefs=wanted.filter((id,i)=>wanted.indexOf(id)!==i);if(duplicateRefs.length)return null;const missing=[],target={...p.equipment};for(const [slot,uid] of Object.entries(l.equipment)){if(!(slot in target))continue;if(!uid){target[slot]=null;continue;}const item=byUid.get(uid),validSlot=item&&(item.slot===slot||item.slot==='ring'&&['ring1','ring2'].includes(slot));if(!validSlot){missing.push(uid);continue;}target[slot]=item;}const seen=new Set();for(const slot of Object.keys(target)){const uid=itemUid(target[slot]);if(uid&&seen.has(uid)){target[slot]=null;missing.push(uid);}else if(uid)seen.add(uid);}const equipped=Object.values(target).filter(Boolean),mythics=equipped.filter(i=>i.rarity==='mythic');if(mythics.length>1)return null;const bankSet=new Set(bankItems),remaining=allItems.filter(item=>!equipped.includes(item)),inventory=remaining.filter(item=>!bankSet.has(item)),bank=remaining.filter(item=>bankSet.has(item));if(inventory.length>p.inventoryCapacity||bank.length>(p.bank?.capacity||80))return null;const validTalents=(l.talents||[]).filter(id=>{const node=findTalent(p.classId,id);return node&&node.specialization===l.specialization;});const totalTalentPoints=(p.talentPoints||0)+(p.talents||[]).length;if(validTalents.length>totalTalentPoints)return null;const validSkills=(l.skills||[]).filter(id=>{const skill=SKILLS[id]||SPEC_SKILLS[id];return skill&&skill.classId===p.classId&&p.level>=skill.requiredLevel&&(!skill.specialization||skill.specialization===l.specialization);}).slice(0,5);p.inventory=inventory;p.bank.tabs[0]=bank;p.equipment={...equipmentShape(),...target};p.specialization=l.specialization;p.talents=validTalents;p.talentPoints=totalTalentPoints-validTalents.length;p.selectedSkills=validSkills;if(l.activePet&&p.pets.owned[l.activePet])p.pets.active=l.activePet;else if(l.activePet)missing.push(`pet:${l.activePet}`);else p.pets.active=null;p.activeLoadout=index;saveGame(game);return {...l,missing,applied:equipped.map(itemUid)};}

function obtainPet(game,id,{save=true}={}){const data=PETS[id],owned=game.player.pets.owned;if(!data)return false;if(!owned[id])owned[id]={id,level:1,exp:0,unlocks:[]};game.collections.pets.includes(id)||game.collections.pets.push(id);if(!game.player.pets.active)game.player.pets.active=id;if(save)saveGame(game);return true;}
function setActivePet(game,id){if(!game.player.pets.owned[id])return false;game.player.pets.active=id;saveGame(game);return true;}
function setActiveMount(game,id){if(!game.player.mounts.owned.includes(id)||!MOUNTS[id])return false;game.player.mounts.active=id;saveGame(game);return true;}
function gainPetExperience(game,amount=10){const id=game.player.pets.active,pet=game.player.pets.owned[id];if(!pet)return [];pet.exp+=amount;const levels=[];while(pet.level<30&&pet.exp>=80+pet.level*35){pet.exp-=80+pet.level*35;pet.level++;if([5,10,20].includes(pet.level))pet.unlocks.push(`Mejora ${pet.level}`);levels.push(pet.level);}return levels;}
function trainPet(game,id){const pet=game.player.pets.owned[id];if(!pet||pet.level>=30)return null;const cost=1+Math.floor(pet.level/5);if((game.player.materials.petEssence||0)<cost)return null;game.player.materials.petEssence-=cost;pet.exp+=45+pet.level*5;const levels=[];while(pet.level<30&&pet.exp>=80+pet.level*35){pet.exp-=80+pet.level*35;pet.level++;if([5,10,20].includes(pet.level))pet.unlocks.push(`Mejora ${pet.level}`);levels.push(pet.level);}saveGame(game);return {cost,levels};}
function evolvePet(game,id){const owned=game.player.pets.owned[id],data=PETS[id],evolution=data?.evolution;if(!owned||!evolution||owned.evolutionStage>=2||owned.level<evolution.level)return null;const cost=evolution.cost*(owned.evolutionStage+1);if((game.player.materials[evolution.material]||0)<cost)return null;game.player.materials[evolution.material]-=cost;owned.evolutionStage=(owned.evolutionStage||0)+1;owned.unlocks.push(owned.evolutionStage===1?'FORMA EVOLUCIONADA':'FORMA ANCESTRAL');saveGame(game);return {stage:owned.evolutionStage,cost};}
function gainReputation(game,factionId,amount){const rep=game.factions[factionId];if(!rep)return false;rep.value=Math.min(9999,whole(rep.value,0,9999,0)+whole(amount,0,9999,0));return true;}
function claimReputationReward(game,factionId,rank){const rep=game.factions[factionId],needs={friendly:500,honored:1500,revered:3500,exalted:7000};if(!rep||rep.value<(needs[rank]||Infinity)||rep.claimed.includes(rank))return false;const reward=rank==='friendly'?{materials:{reforgeStone:2}}:rank==='honored'?{gems:{sapphire1:1}}:rank==='revered'?{pets:[factionId==='abyss'?'specter':'ironCub']}:rank==='exalted'?{mounts:[factionId==='arcane'?'arcaneTiger':factionId==='abyss'?'spectralHorse':'warWolf']}:null;if(!reward)return false;const result=deliverRewards(game,reward,{transactionId:`reputation:${factionId}:${rank}`,save:false});if(!result.ok&&!result.duplicate)return false;rep.claimed.push(rank);saveGame(game);return true;}
function buyFactionItem(game,factionId,itemId){const stock=FACTION_STOCK[factionId]?.find(item=>item.id===itemId),rep=game.factions[factionId],needs={friendly:500,honored:1500,revered:3500,exalted:7000},p=game.player;if(!stock||!rep||rep.value<(needs[stock.rank]||Infinity)||p.gold<stock.price)return false;const reward=stock.reward;if(reward.pet&&p.pets.owned[reward.pet]||reward.mount&&p.mounts.owned.includes(reward.mount)||reward.recipe&&p.learnedRecipes.includes(reward.recipe))return false;p.gold-=stock.price;for(const [id,n] of Object.entries(reward.materials||{}))p.materials[id]=(p.materials[id]||0)+n;if(reward.gem)p.gems[reward.gem]=(p.gems[reward.gem]||0)+1;if(reward.recipe)p.learnedRecipes.push(reward.recipe);if(reward.pet)obtainPet(game,reward.pet);if(reward.mount){p.mounts.owned.push(reward.mount);game.collections.mounts.includes(reward.mount)||game.collections.mounts.push(reward.mount);}saveGame(game);return true;}
function progressContract(game,type,amount=1,id=null){const list=[...(game.contracts.daily||[]),game.contracts.weekly].filter(Boolean);for(const c of list)if(!c.complete&&c.type===type&&(!c.objectiveId||c.objectiveId===id)){c.progress=Math.min(c.target,(c.progress||0)+amount);c.complete=c.progress>=c.target;}}
function claimContract(game,id){const c=[...(game.contracts.daily||[]),game.contracts.weekly].find(x=>x?.id===id);if(!c?.complete||c.claimed)return false;const tx=`contract:${game.contracts.dailyDate}:${game.contracts.weeklyDate}:${id}`,result=deliverRewards(game,c.reward,{transactionId:tx,save:false});if(!result.ok)return false;c.claimed=true;saveGame(game);return true;}
function acceptBounty(game){const bounty=game.bounty;if(!bounty||bounty.claimed)return false;bounty.accepted=true;saveGame(game);return true;}
function claimBounty(game){const bounty=game.bounty;if(!bounty?.complete||bounty.claimed)return false;const result=deliverRewards(game,bounty.reward,{transactionId:`bounty:${bounty.date}:${bounty.targetId}`,save:false});if(!result.ok)return false;bounty.claimed=true;saveGame(game);return true;}
function claimMailbox(game){let count=0;for(const mail of game.player.mailbox)if(!mail.claimed){const result=deliverRewards(game,mail.reward,{transactionId:`mail:${mail.id}`,save:false});if(result.ok){mail.claimed=true;count++;}else if(result.duplicate)mail.claimed=true;}saveGame(game);return count;}
const LOCAL_PROMOTIONS={'CQV4-DEV':{gold:50,materials:{iron:2}}};
function redeemPromotion(game,rawCode){const code=String(rawCode||'').trim().toUpperCase(),reward=LOCAL_PROMOTIONS[code];if(!reward||game.promotions.claimed.includes(code))return false;game.promotions.claimed.push(code);game.player.mailbox.push({id:`promo-${code}`,subject:'Código promocional local',reward:clone(reward),claimed:false,at:Date.now()});saveGame(game);return true;}

function equipRecommended(game){const p=game.player,magic=['mage','necromancer'].includes(p.classId),weights=magic?{magic:3,intelligence:2.2,maxMana:.08,crit:1.5,defense:.7,maxHp:.05}:{attack:3,strength:2.2,agility:1.5,crit:1.7,defense:.8,maxHp:.05};if(['guardian','protector'].includes(p.specialization))Object.assign(weights,{defense:2.5,maxHp:.14,armor:2});const score=item=>Object.entries(item?.stats||{}).reduce((n,[k,v])=>n+v*(weights[k]||.3),0)+(item?.unique?12:0);let changed=0;for(const item of [...p.inventory].filter(i=>i.type==='equipment').sort((a,b)=>score(b)-score(a))){let slot=item.slot;if(slot==='ring'){const first=score(p.equipment.ring1),second=score(p.equipment.ring2);slot=first<=second?'ring1':'ring2';}const current=p.equipment[slot];if(score(item)>score(current)*1.05&&!(item.rarity==='mythic'&&Object.entries(p.equipment).some(([s,i])=>s!==slot&&i?.rarity==='mythic'))){const uid=itemUid(item),index=p.inventory.findIndex(i=>itemUid(i)===uid);if(index<0)continue;p.equipment[slot]=item;p.inventory.splice(index,1);if(current)p.inventory.push(current);changed++;}}if(changed)saveGame(game);return changed;}

function removeConsumableStack(player,item){item.quantity=whole(item.quantity,1,9999,1)-1;if(item.quantity<=0)player.inventory.splice(player.inventory.indexOf(item),1);}
function consumePotion(game,kind='hp'){
  const p=game.player,candidates=kind==='mana'?['manaPotion']:kind==='cleanse'?['greaterAntidote','antidote']:['superiorPotion','potion','resourcePotion'];
  const potion=p.inventory.find(i=>i.type==='consumable'&&candidates.includes(i.baseId)&&i.quantity>0);if(!potion)return null;
  const consumed={...potion,cleanse:[...(potion.cleanse||[])]};removeConsumableStack(p,potion);saveGame(game);return consumed;
}
function consumeInventoryItem(game,itemId){
  const p=game.player,item=p.inventory.find(i=>(i.uid===itemId||i.id===itemId)&&i.type==='consumable'&&i.quantity>0);if(!item)return null;
  const stats=calculateStats(p),effects=[];
  if(item.heal&&p.currentHp<stats.maxHp){const amount=Math.min(whole(item.heal,0,999999,0),stats.maxHp-p.currentHp);p.currentHp+=amount;effects.push({type:'heal',amount});}
  if(item.mana&&p.currentMana<stats.maxMana){const amount=Math.min(whole(item.mana,0,999999,0),stats.maxMana-p.currentMana);p.currentMana+=amount;effects.push({type:'mana',amount});}
  if(isObject(item.buff)){
    const buffStats={};for(const [key,value] of Object.entries(item.buff)){const safe=finite(value,0);if(safe)buffStats[key]=safe;}
    if(Object.keys(buffStats).length){game.temporaryBuffs.push({id:`consumable-${item.baseId}-${Date.now()}-${Math.random().toString(16).slice(2,8)}`,name:item.name,stats:buffStats,expiresCombats:3});effects.push({type:'buff',combats:3,stats:buffStats});}
  }
  if(!effects.length)return null;
  const consumed={...item,cleanse:[...(item.cleanse||[])]};removeConsumableStack(p,item);saveGame(game);return {item:consumed,effects};
}
function spendEnergy(game,amount){const numeric=Number(amount);if(!Number.isFinite(numeric)||numeric<=0)return false;const cost=whole(numeric,1,10000,1);regenerateOffline(game);if(game.energy.current<cost)return false;game.energy.current=Math.max(0,game.energy.current-cost);game.energy.lastUpdate=Date.now();saveGame(game);return true;}
function restAtCity(game){game.activeTab='more';game.moreScreen='city';game.recovery=game.recovery||{};game.recovery.inSafeZone=true;game.recovery.lastUpdate=Date.now();saveGame(game);return true;}

function acceptQuest(game,id){const q=QUESTS[id];if(!q||q.requires&&!game.quests.claimed.includes(q.requires)||game.quests.active.includes(id)||game.quests.completed.includes(id))return false;game.quests.active.push(id);saveGame(game);return true;}
