function addZoneMastery(game,zoneId,amount=1,reason='exploración'){
  if(!zoneId)return [];const before=Math.max(0,Math.min(100,game.zoneMastery[zoneId]||0)),after=Math.max(before,Math.min(100,before+amount));game.zoneMastery[zoneId]=after;game.zoneMilestones[zoneId]||=[];const claimed=[];
  for(const [value,data] of Object.entries(ZONE_MILESTONES))if(after>=Number(value)&&before<Number(value)&&!game.zoneMilestones[zoneId].includes(Number(value))){game.zoneMilestones[zoneId].push(Number(value));deliverRewards(game,data.reward,{transactionId:`zone:${zoneId}:${value}`,save:false});claimed.push(Number(value));game.notifications.push({type:'zone',text:`${data.name.toUpperCase()} · ${zoneId} ${value}%`,at:Date.now()});}
  if(after>before)game.notifications.push({type:'zoneProgress',text:`DOMINIO +${after-before}% · ${reason}`,at:Date.now()});return claimed;
}

function toggleWishlist(game,id){if(!id)return false;const index=game.wishlist.indexOf(id);if(index>=0)game.wishlist.splice(index,1);else game.wishlist.push(id);saveGame(game);return index<0;}

function startExpedition(game,tier=1){if(game.expeditions.active)return game.expeditions.active;if(tier>game.expeditions.bestTier||tier>5)return null;game.expeditions.active=makeExpedition(tier);saveGame(game);return game.expeditions.active;}
function chooseExpeditionNode(game,index){const run=game.expeditions.active;if(!run||run.status!=='active'||index<0||index>1)return null;const stages=[['combat','elite'],['event','treasure'],['combat','elite'],['rest','merchant'],['elite','treasure'],['boss']];const type=stages[run.stage]?.[index]||stages[run.stage]?.[0];if(!type)return null;const node={stage:run.stage,type,risk:index?'danger':'safe',resolved:false};run.path.push(node);saveGame(game);return node;}
function resolveExpeditionNode(game,{relic=false}={}){const run=game.expeditions.active,node=run?.path.at(-1);if(!run||!node||node.resolved)return null;node.resolved=true;if(relic){const pool=Object.keys(EXPEDITION_RELICS).filter(id=>!run.relics.includes(id));if(pool.length)run.relics.push(pool[(run.seed+run.stage)%pool.length]);}run.stage++;saveGame(game);return node;}
function completeExpedition(game){const run=game.expeditions.active;if(!run||run.stage<6)return null;run.status='completed';const reward={gold:350*run.tier,materials:{reforgeStone:run.tier,bossCore:Math.ceil(run.tier/2),legendaryShard:run.tier>=4?1:0},reputation:{arcane:60*run.tier}},result=deliverRewards(game,reward,{transactionId:`expedition:${run.id}`,save:false});if(!result.ok)return null;game.expeditions.completed++;game.expeditions.bestTier=Math.min(5,Math.max(game.expeditions.bestTier,run.tier<5?run.tier+1:5));game.expeditions.history.unshift({id:run.id,tier:run.tier,relics:[...run.relics],at:Date.now()});game.expeditions.history=game.expeditions.history.slice(0,12);game.expeditions.active=null;saveGame(game);return {reward,result};}

function recordNemesisDefeat(game,enemy){if(!enemy?.elite||enemy.boss)return null;const previous=game.nemesis&&game.nemesis.baseId===enemy.id?game.nemesis:null;game.nemesis={baseId:enemy.id,name:previous?.name||`${enemy.name} · NÉMESIS`,family:enemy.family,zone:enemy.zone,level:Math.max(enemy.level,previous?.level||0),affixes:[...(enemy.eliteAffixes||[])],victories:(previous?.victories||0)+1,lastSeen:Date.now()};saveGame(game);return game.nemesis;}
function defeatNemesis(game){const nemesis=game.nemesis;if(!nemesis)return null;const reward={gold:180+nemesis.victories*90,materials:{reforgeStone:1+nemesis.victories,legendaryShard:nemesis.victories>=3?1:0}};deliverRewards(game,reward,{transactionId:`nemesis:${nemesis.baseId}:${nemesis.victories}`,save:false});game.notifications.push({type:'nemesis',text:`NÉMESIS DERROTADA · ${nemesis.name}`,at:Date.now()});game.nemesis=null;return reward;}

function gainSpecializationMastery(game,amount=6){const id=game.player.specialization;if(!id)return null;const m=game.specializationMastery[id]||(game.specializationMastery[id]={level:1,exp:0});m.exp+=amount;const cap=20;while(m.level<cap&&m.exp>=80+m.level*25){m.exp-=80+m.level*25;m.level++;if(m.level%5===0)deliverRewards(game,{materials:{reforgeStone:1}},{transactionId:`specMastery:${id}:${m.level}`,save:false});}return m;}


