const RELEASE_STAGE='ALPHA 0.1',BUILD_LABEL='V18 PRE-LAUNCH',RAPID_ACTION_WINDOW_MS=300;
let criticalActionLockedUntil=0,lastCriticalActionKey='';
const criticalActionKeys=new Set(['combat','skill','buy','sell','equip','equipped','rewardItem','talent','attribute','craft','smith','contract','claimQuest','repReward','factionBuy','dungeon','fight','eventChoice','startExpedition','expeditionNode','trainPet','evolvePet','bankStore','bankTake','transmute','transmuteGem']);
