function blockRapidCriticalAction(button){const datasetKey=Object.keys(button.dataset).find(key=>criticalActionKeys.has(key)),actionKey=criticalActions.has(button.dataset.action)?button.dataset.action:null;if(!datasetKey&&!actionKey)return false;const key=['combat','skill'].includes(datasetKey)?'combat':datasetKey||actionKey,now=performance.now();if(key===lastCriticalActionKey&&now<criticalActionLockedUntil)return true;lastCriticalActionKey=key;criticalActionLockedUntil=now+RAPID_ACTION_WINDOW_MS;return false;}
