const esc=(v='')=>String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const pct=(v,m)=>Math.max(0,Math.min(100,(v/m)*100||0));
const bar=(kind,value,max,label='')=>`<div class="stat-bar ${kind}"><div class="bar-caption"><span>${iconMarkup({hp:'hp',mana:'mana',exp:'exp',resource:'arcane',energy:'energy'}[kind]||'arcane','✦','bar-icon')} ${label}</span><b>${Math.ceil(value)}/${Math.ceil(max)}</b></div><div class="bar-track"><i style="width:${pct(value,max)}%"></i></div></div>`;
function toast(message,type=''){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=String(message);toastLayer.append(el);setTimeout(()=>el.remove(),2400);}
function triggerHaptic(type='tap'){const patterns={tap:10,defend:[16,24,16],critical:[18,25,28],legendary:[20,35,20,35,45],levelUp:[18,22,18,22,35],bossVictory:[30,28,45]};if(game?.settings?.vibration&&navigator.vibrate)navigator.vibrate(patterns[type]||patterns.tap);}
function tutorialTip(id,message){const seen=game?.runtime?.tutorialSeen;if(!game?.settings?.tutorial||!Array.isArray(seen)||seen.includes(id))return;seen.push(id);saveGame(game);toast(message,'success');}
