function effectiveItemStats(item){const stats={},add=source=>{for(const [key,value] of Object.entries(source||{}))if(Number.isFinite(Number(value)))stats[key]=(stats[key]||0)+Number(value);};if(!item)return stats;const upgrade=1+(item.upgrade||0)*.06;add(Object.fromEntries(Object.entries(item.stats||{}).map(([key,value])=>[key,Number(value)*upgrade])));add(item.effectData?.stats);for(const id of item.runes||[])add(RUNES[id]?.stats);for(const id of item.gems||[])add(GEMS[id]?.stats);for(const id of item.mechanicRunes||[])add(MECHANIC_RUNES[id]?.stats);return stats;}
