  if(button.dataset.npc){if(!game.codex.npcs.includes(button.dataset.npc)){game.codex.npcs.push(button.dataset.npc);saveGame(game);}modal={type:'npc',id:button.dataset.npc};render();return;}
  if(button.dataset.storyChoice){game.story.flags[button.dataset.storyChoice]=true;game.story.seenDialogues.includes(button.dataset.storyChoice)||game.story.seenDialogues.push(button.dataset.storyChoice);saveGame(game);modal=null;toast('Decisión registrada','success');render();return;}
  if(button.dataset.combat){resolveCombatAction(button.dataset.combat);return;}
