  if(button.dataset.rewardItem){const item=combatReward?.loot;if(!item)return;if(button.dataset.rewardItem==='view'){const stats=Object.entries(item.stats||{}).map(([key,value])=>`${statName(key)} +${value}`).join(' · ');combat.logs.unshift({type:'victory',text:`${item.name} · ${rarityLabel(item.rarity)} · ${stats} · ${item.effect||'Sin efecto único'}`});modal='log';render();return;}if(button.dataset.rewardItem==='equip'){const ok=equipItem(game,item.uid||item.id);toast(ok?'Legendario equipado':'No se puede equipar',ok?'success':'');render();return;}if(button.dataset.rewardItem==='bank'){const ok=moveBankItem(game,item.uid||item.id,true);toast(ok?'Legendario guardado en banco':'Banco lleno o objeto ya movido',ok?'success':'');render();return;}}
