  if(button.dataset.talent){if(learnTalent(game,button.dataset.talent)){toast('Talento aprendido','success');render();}return;}
  if(button.dataset.upgradeSkill){if(upgradeSkill(game,button.dataset.upgradeSkill)){toast('Habilidad mejorada','success');render();}return;}
  if(button.dataset.skillMod){const [skillId,level,optionId]=button.dataset.skillMod.split(':'),ok=chooseSkillModifier(game,skillId,Number(level),optionId);toast(ok?'Modificador de habilidad elegido':'Modificador no disponible',ok?'success':'');render();return;}
