  if(button.dataset.rune&&selectedItem){const ok=applyRune(game,selectedItem.uid||selectedItem.id,button.dataset.rune);toast(ok?'Runa aplicada':'No se puede aplicar',ok?'success':'');render();return;}
  if(button.dataset.removeRune!=null&&selectedItem){const r=removeRune(game,selectedItem.uid||selectedItem.id,Number(button.dataset.removeRune));toast(r?`Runa retirada · ${r.cost} oro`:'Oro insuficiente',r?'success':'');render();return;}if(button.dataset.gem&&selectedItem){const ok=applyGem(game,selectedItem.uid||selectedItem.id,button.dataset.gem);toast(ok?'Gema engarzada':'No se puede engarzar',ok?'success':'');render();return;}
  if(button.dataset.removeGem!=null&&selectedItem){const r=removeGem(game,selectedItem.uid||selectedItem.id,Number(button.dataset.removeGem));toast(r?`Gema retirada · ${r.cost} oro`:'Oro insuficiente',r?'success':'');render();return;}
  if(button.dataset.mechanicRune&&selectedItem){const ok=applyMechanicRune(game,selectedItem.uid||selectedItem.id,button.dataset.mechanicRune);toast(ok?'Runa mecánica aplicada':'No se puede aplicar',ok?'success':'');render();return;}
  if(button.dataset.removeMechanicRune!=null&&selectedItem){const r=removeMechanicRune(game,selectedItem.uid||selectedItem.id,Number(button.dataset.removeMechanicRune));toast(r?`Runa retirada · ${r.cost} oro`:'Oro insuficiente',r?'success':'');render();return;}
  if(button.dataset.reforge){const itemId=modal.item.uid||modal.item.id,r=reforgeAffix(game,itemId,button.dataset.reforge);modal=null;selectedItem=[...game.player.inventory,...Object.values(game.player.equipment).filter(Boolean)].find(i=>i.uid===itemId||i.id===itemId);toast(r?`${statName(r.from)} → ${statName(r.to)} +${r.value}`:'Faltan oro o Piedras de Reforja',r?'success':'');render();return;}
